/* prog28_levenshtein – reconstructed from the obfuscated binary
 *
 * Behaviour:
 *   - If the program is invoked with fewer than 2 arguments
 *       (i.e. argc < 3) it prints the line "USAGE" and exits.
 *   - The two arguments are interpreted as the strings whose
 *       Levenshtein distance is to be computed.
 *   - If either string is longer than 64 characters the program
 *       prints the line "TOO_LONG" and exits.
 *   - Otherwise it computes the classic Levenshtein edit distance
 *       (insert, delete, substitution) and prints the distance as
 *       a decimal number followed by a newline.
 *
 * The original binary used a static 65×65 integer matrix (named
 * `main_dp` in the disassembly) and filled the first row/column
 * with the indices 0..len.  The rest of the matrix is filled with
 * the minimum‑cost recurrence.
 *
 * The implementation below follows the same algorithm and limits,
 * but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <string.h>

#define MAXLEN 64          /* maximum length accepted for each string */
#define DP_SIZE (MAXLEN+1) /* matrix dimension (including the zero row/col) */

/* static matrix – matches the original binary's global `main_dp` */
static int dp[DP_SIZE][DP_SIZE];

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
     * Argument handling
     * ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    size_t len1 = strlen(s1);
    size_t len2 = strlen(s2);

    if (len1 > MAXLEN || len2 > MAXLEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* -----------------------------------------------------------------
     * Initialise first row and column of the DP matrix
     * ----------------------------------------------------------------- */
    for (size_t i = 0; i <= len1; ++i)
        dp[i][0] = (int)i;          /* deletions */
    for (size_t j = 0; j <= len2; ++j)
        dp[0][j] = (int)j;          /* insertions */

    /* -----------------------------------------------------------------
     * Fill the matrix using the Levenshtein recurrence
     * ----------------------------------------------------------------- */
    for (size_t i = 1; i <= len1; ++i) {
        for (size_t j = 1; j <= len2; ++j) {
            int cost = (s1[i-1] == s2[j-1]) ? 0 : 1;

            int del = dp[i-1][j] + 1;          /* deletion */
            int ins = dp[i][j-1] + 1;          /* insertion */
            int sub = dp[i-1][j-1] + cost;     /* substitution */

            int best = del;
            if (ins < best) best = ins;
            if (sub < best) best = sub;

            dp[i][j] = best;
        }
    }

    /* -----------------------------------------------------------------
     * Output the result
     * ----------------------------------------------------------------- */
    printf("%d\n", dp[len1][len2]);
    return 0;
}
